BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "cache" (
	"key"	varchar NOT NULL,
	"value"	text NOT NULL,
	"expiration"	integer NOT NULL,
	PRIMARY KEY("key")
);
CREATE TABLE IF NOT EXISTS "cache_locks" (
	"key"	varchar NOT NULL,
	"owner"	varchar NOT NULL,
	"expiration"	integer NOT NULL,
	PRIMARY KEY("key")
);
CREATE TABLE IF NOT EXISTS "failed_jobs" (
	"id"	integer NOT NULL,
	"uuid"	varchar NOT NULL,
	"connection"	text NOT NULL,
	"queue"	text NOT NULL,
	"payload"	text NOT NULL,
	"exception"	text NOT NULL,
	"failed_at"	datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "gantt_activities" (
	"id"	INTEGER,
	"master_project_id"	INTEGER NOT NULL,
	"activity_name"	VARCHAR NOT NULL,
	"start_date"	DATE,
	"end_date"	DATE,
	"progress_percentage"	INTEGER DEFAULT 0,
	"created_at"	DATETIME,
	"updated_at"	DATETIME,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("master_project_id") REFERENCES "master_projects"("id")
);
CREATE TABLE IF NOT EXISTS "job_batches" (
	"id"	varchar NOT NULL,
	"name"	varchar NOT NULL,
	"total_jobs"	integer NOT NULL,
	"pending_jobs"	integer NOT NULL,
	"failed_jobs"	integer NOT NULL,
	"failed_job_ids"	text NOT NULL,
	"options"	text,
	"cancelled_at"	integer,
	"created_at"	integer NOT NULL,
	"finished_at"	integer,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "jobs" (
	"id"	integer NOT NULL,
	"queue"	varchar NOT NULL,
	"payload"	text NOT NULL,
	"attempts"	integer NOT NULL,
	"reserved_at"	integer,
	"available_at"	integer NOT NULL,
	"created_at"	integer NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "master_projects" (
	"id"	INTEGER,
	"project_code"	VARCHAR NOT NULL,
	"project_name"	VARCHAR NOT NULL,
	"spreadsheet_id"	VARCHAR,
	"description"	TEXT,
	"created_at"	DATETIME,
	"updated_at"	DATETIME,
	"type"	varchar,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "migrations" (
	"id"	integer NOT NULL,
	"migration"	varchar NOT NULL,
	"batch"	integer NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" (
	"email"	varchar NOT NULL,
	"token"	varchar NOT NULL,
	"created_at"	datetime,
	PRIMARY KEY("email")
);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" (
	"id"	integer NOT NULL,
	"tokenable_type"	varchar NOT NULL,
	"tokenable_id"	integer NOT NULL,
	"name"	text NOT NULL,
	"token"	varchar NOT NULL,
	"abilities"	text,
	"last_used_at"	datetime,
	"expires_at"	datetime,
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "procurement_recommendations" (
	"id"	integer NOT NULL,
	"master_project_id"	integer NOT NULL,
	"procurement_no"	varchar NOT NULL,
	"summary"	text,
	"recommendations"	text NOT NULL,
	"source"	varchar NOT NULL DEFAULT 'ai',
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("master_project_id") REFERENCES "master_projects"("id") on delete cascade
);
CREATE TABLE IF NOT EXISTS "procurements" (
	"id"	INTEGER,
	"master_project_id"	INTEGER NOT NULL,
	"no"	VARCHAR NOT NULL,
	"name"	VARCHAR NOT NULL,
	"vendor"	VARCHAR,
	"nilai_rab"	DECIMAL(15, 2),
	"realisasi"	DECIMAL(15, 2),
	"mata_uang"	VARCHAR DEFAULT 'IDR',
	"status"	VARCHAR DEFAULT 'In Progress',
	"progress"	VARCHAR,
	"priority"	VARCHAR DEFAULT 'Medium',
	"created_at"	DATETIME,
	"updated_at"	DATETIME,
	"target_tgl"	varchar,
	"jenis"	varchar,
	"payment_type"	varchar,
	"proc_policy"	varchar,
	"no_hps"	varchar,
	"tanggal_hps"	varchar,
	"rks"	varchar,
	"tanggal_rks"	varchar,
	"pic_ome"	varchar,
	"no_pr"	varchar,
	"proc_ops"	varchar,
	"no_po"	varchar,
	"kontrak_status"	varchar,
	"due_date"	varchar,
	"payment_priority"	varchar,
	"delivery_status"	varchar,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("master_project_id") REFERENCES "master_projects"("id")
);
CREATE TABLE IF NOT EXISTS "project_links" (
	"id"	INTEGER,
	"master_project_id"	INTEGER NOT NULL,
	"sheet_name"	VARCHAR NOT NULL,
	"sheet_url"	VARCHAR,
	"sheet_key"	VARCHAR,
	"data"	TEXT,
	"row_count"	INTEGER,
	"last_synced_at"	DATETIME,
	"created_at"	DATETIME,
	"updated_at"	DATETIME,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("master_project_id") REFERENCES "master_projects"("id")
);
CREATE TABLE IF NOT EXISTS "project_profiles" (
	"id"	integer NOT NULL,
	"master_project_id"	integer NOT NULL,
	"type"	varchar,
	"project_name"	varchar,
	"pimpro_name"	varchar,
	"report_pic"	varchar,
	"contract_value"	varchar,
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("master_project_id") REFERENCES "master_projects"("id") on delete cascade
);
CREATE TABLE IF NOT EXISTS "sessions" (
	"id"	varchar NOT NULL,
	"user_id"	integer,
	"ip_address"	varchar,
	"user_agent"	text,
	"payload"	text NOT NULL,
	"last_activity"	integer NOT NULL,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "system_syncs" (
	"id"	integer NOT NULL,
	"key"	varchar NOT NULL,
	"last_synced_at"	datetime,
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "tasks" (
	"id"	integer NOT NULL,
	"task_id"	varchar NOT NULL,
	"task_name"	varchar NOT NULL,
	"start_date"	date,
	"end_date"	date,
	"plan_date"	date,
	"actual_date"	date,
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "users" (
	"id"	integer NOT NULL,
	"name"	varchar NOT NULL,
	"email"	varchar NOT NULL,
	"email_verified_at"	datetime,
	"password"	varchar NOT NULL,
	"remember_token"	varchar,
	"created_at"	datetime,
	"updated_at"	datetime,
	PRIMARY KEY("id" AUTOINCREMENT)
);
